  S("s-food07", "food", 1, "물 좀 주세요.", "Can I have some water, please?", "kæn aɪ hæv sʌm ˈwɔːtər pliːz", "请给我水。", "qǐng gěi wǒ shuǐ", "お水をください。", "おみず を ください");
