  S("s-tech15", "tech", 2, "컴퓨터가 너무 느려요.", "My computer is so slow.", "maɪ kəmˈpjuːtər ɪz soʊ sloʊ", "我的电脑太慢了。", "wǒ de diànnǎo tài màn le", "パソコンがとても遅いです。", "ぱそこん が とても おそいです");
  S("s-tech16", "tech", 2, "다시 시작해 보세요.", "Try restarting it.", "traɪ riːˈstɑːrtɪŋ ɪt", "试试重新启动。", "shìshi chóngxīn qǐdòng", "再起動してみてください。", "さいきどう して みて ください");
  S("s-tech17", "tech", 3, "업데이트가 필요해요.", "It needs an update.", "ɪt niːdz ən ˈʌpdeɪt", "需要更新。", "xūyào gēngxīn", "アップデートが必要です。", "あっぷでーと が ひつようです");
  S("s-tech18", "tech", 3, "온라인으로 주문했어요.", "I ordered it online.", "aɪ ˈɔːrdərd ɪt ˌɑːnˈlaɪn", "我是在网上订的。", "wǒ shì zài wǎngshàng dìng de", "オンラインで注文しました。", "おんらいん で ちゅうもん しました");
  S("s-tech19", "tech", 3, "데이터를 다 썼어요.", "I used up all my data.", "aɪ juːzd ʌp ɔːl maɪ ˈdeɪtə", "我的流量用完了。", "wǒ de liúliàng yòng wán le", "データを使い切りました。", "でーた を つかいきりました");
  S("s-tech20", "tech", 3, "이 링크를 클릭하지 마세요.", "Don't click this link.", "doʊnt klɪk ðɪs lɪŋk", "不要点这个链接。", "búyào diǎn zhège liànjiē", "このリンクをクリックしないでください。", "この りんく を くりっく しないで ください");
  // ── 돈·은행·우체국
  S("s-money01", "money", 1, "돈이 없어요.", "I don't have any money.", "aɪ doʊnt hæv ˈeni ˈmʌni", "我没有钱。", "wǒ méiyǒu qián", "お金がありません。", "おかね が ありません");
  S("s-money03", "money", 1, "은행이 어디예요?", "Where is the bank?", "wer ɪz ðə bæŋk", "银行在哪里？", "yínháng zài nǎli", "銀行はどこですか？", "ぎんこう は どこですか");
  S("s-money04", "money", 1, "잔돈 있어요?", "Do you have change?", "duː juː hæv tʃeɪndʒ", "你有零钱吗？", "nǐ yǒu língqián ma", "小銭はありますか？", "こぜに は ありますか");
  S("s-money05", "money", 1, "영수증 주세요.", "Receipt, please.", "rɪˈsiːt pliːz", "请给我收据。", "qǐng gěi wǒ shōujù", "レシートをください。", "れしーと を ください");
  S("s-money06", "money", 1, "이거 공짜예요?", "Is this free?", "ɪz ðɪs friː", "这个是免费的吗？", "zhège shì miǎnfèi de ma", "これは無料ですか？", "これ は むりょうですか");
  S("s-money07", "money", 1, "우표 한 장 주세요.", "One stamp, please.", "wʌn stæmp pliːz", "请给我一张邮票。", "qǐng gěi wǒ yì zhāng yóupiào", "切手を一枚ください。", "きって を いちまい ください");
  S("s-money08", "money", 1, "제가 낼게요.", "It's on me.", "ɪts ɑːn miː", "我来付。", "wǒ lái fù", "私が払います。", "わたし が はらいます");
  S("s-money09", "money", 2, "돈을 좀 찾고 싶어요.", "I'd like to withdraw some money.", "aɪd laɪk tə wɪðˈdrɔː sʌm ˈmʌni", "我想取点钱。", "wǒ xiǎng qǔ diǎn qián", "お金を少し下ろしたいです。", "おかね を すこし おろしたいです");
  S("s-money10", "money", 2, "계좌를 만들고 싶어요.", "I'd like to open an account.", "aɪd laɪk tə ˈoʊpən ən əˈkaʊnt", "我想开个账户。", "wǒ xiǎng kāi ge zhànghù", "口座を作りたいです。", "こうざ を つくりたいです");
  S("s-money11", "money", 2, "이 소포를 한국으로 보내 주세요.", "Please send this package to Korea.", "pliːz send ðɪs ˈpækɪdʒ tə kəˈriːə", "请把这个包裹寄到韩国。", "qǐng bǎ zhège bāoguǒ jì dào Hánguó", "この小包を韓国に送ってください。", "この こづつみ を かんこく に おくって ください");
  S("s-money12", "money", 2, "ATM이 어디 있어요?", "Where is the ATM?", "wer ɪz ði ˌeɪtiːˈem", "自动取款机在哪里？", "zìdòng qǔkuǎnjī zài nǎli", "ATMはどこですか？", "えーてぃーえむ は どこですか");
  S("s-money13", "money", 2, "우편 요금이 얼마예요?", "How much is the postage?", "haʊ mʌtʃ ɪz ðə ˈpoʊstɪdʒ", "邮费多少钱？", "yóufèi duōshao qián", "郵便料金はいくらですか？", "ゆうびんりょうきん は いくらですか");
  S("s-money14", "money", 2, "거스름돈이 틀려요.", "The change is wrong.", "ðə tʃeɪndʒ ɪz rɔːŋ", "钱找错了。", "qián zhǎo cuò le", "お釣りが間違っています。", "おつり が まちがって います");
  S("s-money15", "money", 2, "매달 저축하고 있어요.", "I save money every month.", "aɪ seɪv ˈmʌni ˈevri mʌnθ", "我每个月都存钱。", "wǒ měi ge yuè dōu cún qián", "毎月貯金しています。", "まいつき ちょきん して います");
  S("s-money16", "money", 2, "따로따로 계산할게요.", "We'll pay separately.", "wiːl peɪ ˈsepərətli", "我们分开付。", "wǒmen fēnkāi fù", "別々に払います。", "べつべつ に はらいます");
  S("s-money17", "money", 3, "환율이 어떻게 돼요?", "What's the exchange rate?", "wʌts ði ɪksˈtʃeɪndʒ reɪt", "汇率是多少？", "huìlǜ shì duōshao", "為替レートはいくらですか？", "かわせれーと は いくらですか");
  S("s-money18", "money", 3, "송금하고 싶어요.", "I'd like to transfer money.", "aɪd laɪk tə trænsˈfɜːr ˈmʌni", "我想汇款。", "wǒ xiǎng huìkuǎn", "送金したいです。", "そうきん したいです");
  S("s-money19", "money", 3, "이 카드는 수수료가 있어요?", "Does this card have a fee?", "dʌz ðɪs kɑːrd hæv ə fiː", "这张卡有手续费吗？", "zhè zhāng kǎ yǒu shǒuxùfèi ma", "このカードは手数料がかかりますか？", "この かーど は てすうりょう が かかりますか");
  S("s-money20", "money", 3, "등기로 보내 주세요.", "Please send it by registered mail.", "pliːz send ɪt baɪ ˈredʒɪstərd meɪl", "请用挂号信寄。", "qǐng yòng guàhàoxìn jì", "書留で送ってください。", "かきとめ で おくって ください");
  // ── 신체·외모·패션
  S("s-body01", "body", 1, "눈이 크시네요.", "You have big eyes.", "juː hæv bɪɡ aɪz", "你的眼睛很大。", "nǐ de yǎnjing hěn dà", "目が大きいですね。", "め が おおきいですね", "한국어에서는 칭찬이지만 미국에서는 신체 특징(눈 크기 등)을 직접 언급하면 평가로 들릴 수 있습니다. 칭찬하려면 You have beautiful eyes. 가 안전합니다.");
  S("s-body02", "body", 1, "키가 몇이에요?", "How tall are you?", "haʊ tɔːl ɑːr juː", "你多高？", "nǐ duō gāo", "身長はどのくらいですか？", "しんちょう は どのくらいですか");
  S("s-body03", "body", 1, "손을 씻으세요.", "Wash your hands.", "wɑːʃ jʊr hændz", "请洗手。", "qǐng xǐ shǒu", "手を洗ってください。", "て を あらって ください");
  S("s-body04", "body", 1, "머리를 잘랐어요.", "I got a haircut.", "aɪ ɡɑːt ə ˈherkʌt", "我剪头发了。", "wǒ jiǎn tóufa le", "髪を切りました。", "かみ を きりました");
  S("s-body05", "body", 1, "이 모자 어때요?", "How's this hat?", "haʊz ðɪs hæt", "这个帽子怎么样？", "zhège màozi zěnmeyàng", "この帽子はどうですか？", "この ぼうし は どうですか");
  S("s-body06", "body", 1, "배가 아파요.", "My stomach hurts.", "maɪ ˈstʌmək hɜːrts", "我肚子疼。", "wǒ dùzi téng", "お腹が痛いです。", "おなか が いたいです");
  S("s-body07", "body", 1, "신발 사이즈가 뭐예요?", "What's your shoe size?", "wʌts jʊr ʃuː saɪz", "你穿多大的鞋？", "nǐ chuān duō dà de xié", "靴のサイズはいくつですか？", "くつ の さいず は いくつですか");
  S("s-body08", "body", 1, "오늘 멋있어요!", "You look great today!", "juː lʊk ɡreɪt təˈdeɪ", "你今天真好看！", "nǐ jīntiān zhēn hǎokàn", "今日は素敵ですね！", "きょう は すてきですね");
  S("s-body09", "body", 2, "이 치마 저한테 어울려요?", "Does this skirt look good on me?", "dʌz ðɪs skɜːrt lʊk ɡʊd ɑːn miː", "这条裙子适合我吗？", "zhè tiáo qúnzi shìhé wǒ ma", "このスカートは私に似合いますか？", "この すかーと は わたし に にあいますか");
  S("s-body10", "body", 2, "다리가 아파요.", "My legs hurt.", "maɪ leɡz hɜːrt", "我腿疼。", "wǒ tuǐ téng", "足が痛いです。", "あし が いたいです");
  S("s-body11", "body", 2, "그녀는 머리가 길어요.", "She has long hair.", "ʃiː hæz lɔːŋ her", "她头发很长。", "tā tóufa hěn cháng", "彼女は髪が長いです。", "かのじょ は かみ が ながいです");
  S("s-body12", "body", 2, "안경을 써요.", "I wear glasses.", "aɪ wer ˈɡlæsɪz", "我戴眼镜。", "wǒ dài yǎnjìng", "眼鏡をかけています。", "めがね を かけて います");
  S("s-body13", "body", 2, "살이 좀 빠졌어요.", "I lost some weight.", "aɪ lɔːst sʌm weɪt", "我瘦了一点。", "wǒ shòu le yìdiǎn", "少し痩せました。", "すこし やせました");
  S("s-body14", "body", 2, "이 바지가 너무 꽉 껴요.", "These pants are too tight.", "ðiːz pænts ɑːr tuː taɪt", "这条裤子太紧了。", "zhè tiáo kùzi tài jǐn le", "このズボンはきつすぎます。", "この ずぼん は きつすぎます");
  S("s-body15", "body", 2, "코트를 입으세요. 추워요.", "Put on your coat. It's cold.", "pʊt ɑːn jʊr koʊt ɪts koʊld", "穿上外套，很冷。", "chuānshang wàitào, hěn lěng", "コートを着てください。寒いです。", "こーと を きて ください さむいです");
  S("s-body16", "body", 2, "아버지를 닮았어요.", "I look like my father.", "aɪ lʊk laɪk maɪ ˈfɑːðər", "我长得像爸爸。", "wǒ zhǎng de xiàng bàba", "父に似ています。", "ちち に にて います");
  S("s-body17", "body", 3, "어깨가 뻐근해요.", "My shoulders are stiff.", "maɪ ˈʃoʊldərz ɑːr stɪf", "我肩膀很酸。", "wǒ jiānbǎng hěn suān", "肩が凝っています。", "かた が こって います");
  S("s-body18", "body", 3, "이 옷 한 사이즈 큰 거 있어요?", "Do you have this in a bigger size?", "duː juː hæv ðɪs ɪn ə ˈbɪɡər saɪz", "这件有大一号的吗？", "zhè jiàn yǒu dà yí hào de ma", "これのワンサイズ上はありますか？", "これ の わんさいず うえ は ありますか");
  S("s-body19", "body", 3, "저는 피부가 민감해요.", "I have sensitive skin.", "aɪ hæv ˈsensətɪv skɪn", "我皮肤很敏感。", "wǒ pífū hěn mǐngǎn", "私は肌が敏感です。", "わたし は はだ が びんかんです");
  S("s-body20", "body", 3, "그 사람은 수염을 길렀어요.", "He grew a beard.", "hiː ɡruː ə bɪrd", "他留了胡子。", "tā liú le húzi", "彼はひげを伸ばしました。", "かれ は ひげ を のばしました");
  // ── 기본 동사 활용
  S("s-verb01", "verb", 1, "저는 매일 운동해요.", "I exercise every day.", "aɪ ˈeksərsaɪz ˈevri deɪ", "我每天运动。", "wǒ měitiān yùndòng", "私は毎日運動します。", "わたし は まいにち うんどうします");
  S("s-verb02", "verb", 1, "이거 열어도 돼요?", "Can I open this?", "kæn aɪ ˈoʊpən ðɪs", "我可以打开这个吗？", "wǒ kěyǐ dǎkāi zhège ma", "これを開けてもいいですか？", "これ を あけても いいですか");
  S("s-verb03", "verb", 1, "물 좀 마실게요.", "I'll drink some water.", "aɪl drɪŋk sʌm ˈwɔːtər", "我喝点水。", "wǒ hē diǎn shuǐ", "水を飲みます。", "みず を のみます");
  S("s-verb04", "verb", 1, "여기 앉으세요.", "Please sit here.", "pliːz sɪt hɪr", "请坐这里。", "qǐng zuò zhèli", "ここに座ってください。", "ここ に すわって ください");
  S("s-verb05", "verb", 1, "문을 닫아 주세요.", "Please close the door.", "pliːz kloʊz ðə dɔːr", "请关门。", "qǐng guān mén", "ドアを閉めてください。", "どあ を しめて ください");
  S("s-verb06", "verb", 1, "잠깐 기다려 주세요.", "Please wait a moment.", "pliːz weɪt ə ˈmoʊmənt", "请稍等。", "qǐng shāo děng", "少し待ってください。", "すこし まって ください");
  S("s-verb07", "verb", 1, "일곱 시에 일어나요.", "I get up at seven.", "aɪ ɡet ʌp æt ˈsevn", "我七点起床。", "wǒ qī diǎn qǐchuáng", "七時に起きます。", "しちじ に おきます");
  S("s-verb08", "verb", 1, "같이 가요.", "Let's go together.", "lets ɡoʊ təˈɡeðər", "一起去吧。", "yìqǐ qù ba", "一緒に行きましょう。", "いっしょ に いきましょう");
  S("s-verb09", "verb", 2, "이거 써 봐도 돼요?", "Can I try this out?", "kæn aɪ traɪ ðɪs aʊt", "我可以试用一下吗？", "wǒ kěyǐ shìyòng yíxià ma", "これを使ってみてもいいですか？", "これ を つかって みても いいですか");
  S("s-verb10", "verb", 2, "뭐 찾고 있어요?", "What are you looking for?", "wʌt ɑːr juː ˈlʊkɪŋ fɔːr", "你在找什么？", "nǐ zài zhǎo shénme", "何を探していますか？", "なに を さがして いますか");
  S("s-verb11", "verb", 2, "그거 저한테 주세요.", "Give that to me, please.", "ɡɪv ðæt tə miː pliːz", "请把那个给我。", "qǐng bǎ nàge gěi wǒ", "それを私にください。", "それ を わたし に ください");
  S("s-verb12", "verb", 2, "불 좀 꺼 주세요.", "Please turn off the light.", "pliːz tɜːrn ɔːf ðə laɪt", "请关灯。", "qǐng guān dēng", "電気を消してください。", "でんき を けして ください");
  S("s-verb13", "verb", 2, "어제 친구를 만났어요.", "I met a friend yesterday.", "aɪ met ə frend ˈjestərdeɪ", "我昨天见了朋友。", "wǒ zuótiān jiàn le péngyou", "昨日友達に会いました。", "きのう ともだち に あいました");
  S("s-verb14", "verb", 2, "창문을 열어 줄래요?", "Could you open the window?", "kʊd juː ˈoʊpən ðə ˈwɪndoʊ", "可以开一下窗吗？", "kěyǐ kāi yíxià chuāng ma", "窓を開けてくれますか？", "まど を あけて くれますか");
  S("s-verb15", "verb", 2, "이거 어떻게 만들어요?", "How do you make this?", "haʊ duː juː meɪk ðɪs", "这个怎么做？", "zhège zěnme zuò", "これはどう作りますか？", "これ は どう つくりますか");
  S("s-verb16", "verb", 2, "열쇠를 잃어버렸어요.", "I lost my key.", "aɪ lɔːst maɪ kiː", "我把钥匙丢了。", "wǒ bǎ yàoshi diū le", "鍵をなくしました。", "かぎ を なくしました");
  S("s-verb17", "verb", 3, "여기에 이름을 써 주세요.", "Please write your name here.", "pliːz raɪt jʊr neɪm hɪr", "请在这里写名字。", "qǐng zài zhèli xiě míngzi", "ここに名前を書いてください。", "ここ に なまえ を かいて ください");
  S("s-verb18", "verb", 3, "나중에 전화해도 돼요?", "Can I call you later?", "kæn aɪ kɔːl juː ˈleɪtər", "我可以晚点给你打电话吗？", "wǒ kěyǐ wǎn diǎn gěi nǐ dǎ diànhuà ma", "後で電話してもいいですか？", "あと で でんわ しても いいですか");
  S("s-verb19", "verb", 3, "가방을 집에 두고 왔어요.", "I left my bag at home.", "aɪ left maɪ bæɡ æt hoʊm", "我把包忘在家里了。", "wǒ bǎ bāo wàng zài jiā li le", "かばんを家に忘れてきました。", "かばん を いえ に わすれて きました");
  S("s-verb20", "verb", 3, "그 사람한테 물어볼게요.", "I'll ask him.", "aɪl æsk hɪm", "我去问问他。", "wǒ qù wènwen tā", "彼に聞いてみます。", "かれ に きいて みます");
  // ── 기본 형용사·부사 활용
  S("s-adj01", "adj", 1, "이게 더 커요.", "This one is bigger.", "ðɪs wʌn ɪz ˈbɪɡər", "这个更大。", "zhège gèng dà", "これの方が大きいです。", "これ の ほう が おおきいです");
  S("s-adj02", "adj", 1, "너무 어려워요.", "It's too hard.", "ɪts tuː hɑːrd", "太难了。", "tài nán le", "難しすぎます。", "むずかしすぎます");
